package net.civeira.phylax.feature.observe.observedalert.domain.gateway;

import java.util.List;
import java.util.Optional;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlertRef;

public interface ObservedAlertQueryRepositoryGateway {

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The items that would be returned by the query
   */
  long count(ObservedAlertFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  boolean exists(String uid, Optional<ObservedAlertFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  Optional<ObservedAlert> find(ObservedAlertFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  List<ObservedAlert> list(ObservedAlertFilter filter);

  /**
   * Retrieve full data for a reference.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param reference a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  ObservedAlert resolve(ObservedAlertRef reference);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  Optional<ObservedAlert> retrieve(String uid, Optional<ObservedAlertFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @param cursor a cursor to order and skip
   * @return The slide with some values
   */
  Slider<ObservedAlert> slide(ObservedAlertFilter filter, ObservedAlertCursor cursor);
}
